Add a test case to verify that invalid API keys (e.g., containing newlines) are correctly rejected during configuration parsing.

```rust
    /// `--worker-api-key` lands in `proxy.worker_api_key`; absent by default.
    #[test]
    fn worker_api_key_flag_parses_into_proxy_config() {
        let c = into_config(&[
            "--model-id",
            "qwen3",
            "--worker-urls",
            "http://x:30000",
            "--worker-api-key",
            "sk-test",
        ])
        .unwrap();
        assert_eq!(c.proxy.worker_api_key.as_deref(), Some("sk-test"));
        let c = into_config(&["--model-id", "qwen3", "--worker-urls", "http://x:30000"]).unwrap();
        assert_eq!(c.proxy.worker_api_key, None);

        // Invalid API key containing a newline should fail validation
        let err = into_config(&[
            "--model-id",
            "qwen3",
            "--worker-urls",
            "http://x:30000",
            "--worker-api-key",
            "sk-test\n",
        ])
        .unwrap_err();
        assert!(err.to_string().contains("contains invalid characters"));
    }
```

